const fs = require('fs');
const vm = require('vm');
const idxHtml = fs.readFileSync('index.html', 'utf8');
const tchHtml = fs.readFileSync('teacher.html', 'utf8');

function extract(html) {
  const c = /<script\s+id=[\x22']local-runtime-cipher[\x22'][^>]*>([\s\S]*?)<\/script>/i.exec(html)[1];
  const s = html.lastIndexOf('<script>'), e = html.lastIndexOf('</script>');
  return { cipher: c, boot: html.slice(s + 8, e) };
}

function makeProbeEnv(rt, searchStr) {
  const els = {};
  const getEl = id => {
    if (id === 'local-runtime-cipher') return { textContent: rt.cipher };
    if (id === 'local-db-vault') return { textContent: '' };
    if (!els[id]) {
      const cardList = [];
      els[id] = {
        id, style: {}, disabled: true, value: '', textContent: '', innerHTML: '',
        classList: { _s: new Set(), add(c){this._s.add(c)}, remove(c){this._s.delete(c)}, contains(c){return this._s.has(c)} },
        children: cardList,
        append(...a){ this.children.push(...a); }, appendChild(a){ this.children.push(a); },
        querySelectorAll(sel){ return sel === '.q-card' ? this.children : []; },
        scrollIntoView(){}, onclick: null
      };
    }
    return els[id];
  };
  const noop = () => {};
  const ctx = {
    fetch, TextEncoder, TextDecoder, btoa, atob, crypto, URLSearchParams,
    Blob: class {}, URL: { createObjectURL: () => '', revokeObjectURL: noop },
    setInterval: noop, clearInterval: noop, setTimeout: noop, alert: noop, scrollTo: noop,
    window: { location: { search: searchStr, pathname: '/', hash: '' }, addEventListener: noop, scrollTo: noop },
    location: { hash: '', search: searchStr, pathname: '/' }, history: { replaceState: noop },
    localStorage: { getItem: () => null, setItem: noop, removeItem: noop },
    document: {
      hidden: false, getElementById: getEl, addEventListener: noop, body: { appendChild: noop },
      createElement: tag => ({
        tagName: tag.toUpperCase(), className: '', style: {}, children: [],
        append(...a){ this.children.push(...a); }, appendChild(a){ this.children.push(a); },
        querySelector(sel){
          const find = cls => {
            for (const lb of this.children) for (const ch of (lb.children||[])) if (String(ch.className||'').includes(cls)) return ch;
            return { value: '' };
          };
          const map = { '.q-text':'q-text', '.q-corr':'q-corr', '.q-w1':'q-w1', '.q-w2':'q-w2', '.q-w3':'q-w3', '.q-exp':'q-exp' };
          return map[sel] ? find(map[sel]) : { value: '' };
        },
        click: noop, scrollIntoView: noop, remove: noop
      })
    }
  };
  ctx.globalThis = ctx;
  return { ctx: vm.createContext(ctx), els };
}

(async () => {
  const tRt = extract(tchHtml);
  const tEnv = makeProbeEnv(tRt, '?quiz=verify_probe_tmp');
  vm.runInContext(tRt.boot, tEnv.ctx);
  await new Promise(r => setTimeout(r, 800));
  tEnv.els['qtitle'].value = 'Probe Quiz';
  tEnv.els['questions-container'].children[0].querySelector('.q-text').value = '2+2?';
  tEnv.els['questions-container'].children[0].querySelector('.q-corr').value = '4';
  tEnv.els['save-btn'].onclick();
  await new Promise(r => setTimeout(r, 1200));
  console.log('Hardened teacher save status:', tEnv.els['status-msg'].textContent);

  const iRt = extract(idxHtml);
  const iEnv = makeProbeEnv(iRt, '?quiz=verify_probe_tmp');
  vm.runInContext(iRt.boot, iEnv.ctx);
  await new Promise(r => setTimeout(r, 1200));
  console.log('Hardened index loaded probe title:', iEnv.els['title'].textContent, 'go.disabled:', iEnv.els['go'].disabled);

  const delUrl = 'https://firestore.googleapis.com/v1/projects/sir-jasper-quiz/databases/(default)/documents/quizzes/verify_probe_tmp';
  const dRes = await fetch(delUrl, { method: 'DELETE' });
  console.log('Probe quiz doc cleanup HTTP:', dRes.status);
})();
